const cellKey=(x,y)=>\`\${x},\${y}\`;
const parseKey=k=>k.split(',').map(Number);
const countNeighbors=(x,y,living)=>{let c=0;for(let dx=-1;dx<=1;dx++)for(let dy=-1;dy<=1;dy++){if(dx===0&&dy===0)continue;if(living.has(cellKey(x+dx,y+dy)))c++;}return c;};
const nextGen=cells=>{const living=new Set(cells.map(([x,y])=>cellKey(x,y)));const candidates=new Set();for(const key of living){const[x,y]=parseKey(key);for(let dx=-1;dx<=1;dx++)for(let dy=-1;dy<=1;dy++)candidates.add(cellKey(x+dx,y+dy));}const next=[];for(const key of candidates){const[x,y]=parseKey(key);const n=countNeighbors(x,y,living);const alive=living.has(key);if(alive&&(n===2||n===3))next.push([x,y]);else if(!alive&&n===3)next.push([x,y]);}return next;};
const input=[[0,0],[1,0],[2,0],[1,1],[0,2],[1,2],[2,2]];
console.log(nextGen(input));
for (const k of input) { const [x,y]=k; console.log(k, countNeighbors(x,y,new Set(input.map(([a,b])=>cellKey(a,b))))); }
"

